mapper.select:
SELECT PRODUCTID, CATEGORYID, CATEGORYNAME, PNM, PRICE, QTY,

IMGNM, row_num FROM ( SELECT a.PRODUCTID, a.CATEGORYID, CASE TO_CHAR(a.CATEGORYID) WHEN '1' THEN '과일류' WHEN '2' THEN '채소류' WHEN '3' THEN '육류' WHEN '4' THEN '어류' WHEN '5' THEN '밀키트' ELSE '기타' END AS CATEGORYNAME, a.PNM, a.PRICE, a.QTY,

NVL(b.IMGNM, '') AS IMGNM, ROW_NUMBER() OVER(ORDER BY a.PRODUCTID DESC) AS row_num FROM PRODUCTS a LEFT JOIN ( SELECT PRODUCTID, IMGNM FROM ( SELECT PRODUCTID, IMGNM, ROW_NUMBER() OVER(PARTITION BY PRODUCTID ORDER BY IMGNM ASC) as rn FROM p_Gallery ) WHERE rn = 1 ) b ON a.PRODUCTID = b.PRODUCTID

a.delyn = 'N'
 AND a.CATEGORYID = #{searchValue} 
 AND a.PNM LIKE '%' || #{searchType} || '%' 

) products_numrow_view WHERE row_num BETWEEN #{begin} AND #{end}
